	MANUELLE_BUCHUNG_FG NUMBER(38,0) COMMENT 'wird aus Tabelle statusmeldung_1 aggregiert. Ist gleich 1, wenn mindestens eine_1 Statusmeldung_1 zu dem Beleg als manuell gekennzeichnet ist',
	OCR_EINGANGSKANAL_ID VARCHAR(1) NOT NULL DEFAULT ' ' COMMENT 'ID des OCR Eingangskanal (''M''=Mail, ''P''=Papier oder leer('' '')',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Waehrung, z.Bsp. CZK, EUR',
	constraint PK_BESCH_RECH_K_VORGANG primary key (SYSTEM_ID, MANDANT_ID, RECH_BELEG_ID, GJ, BELEG_TYP_ID)
